/// 当前连接路线。
enum BridgeConnectionMode { direct, webVpn }

/// Dart 可捕获的 typed 安全错误。
class BridgeError implements FrbException {
  final BridgeErrorCode code;
  final BridgeErrorKind kind;
  final bool retryable;
  final String message;
  final BridgeConnectionMode? resolvedRoute;

  /// 与学校错误分列，不从message推断本地故障。
  final BridgeCacheFailure? cacheFailure;

  const BridgeError({
    required this.code,
    required this.kind,
    required this.retryable,
    required this.message,
    this.resolvedRoute,
    this.cacheFailure,
  });

  @override
  int get hashCode =>
      code.hashCode ^
      kind.hashCode ^
      retryable.hashCode ^
      message.hashCode ^
      resolvedRoute.hashCode ^
      cacheFailure.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeError &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          kind == other.kind &&
          retryable == other.retryable &&
          message == other.message &&
          resolvedRoute == other.resolvedRoute &&
          cacheFailure == other.cacheFailure;
}

/// Core 与 bridge 共用的机器错误码。
enum BridgeErrorCode {
  cacheIdentityMismatch,
  invalidInput,
  authenticationRequired,
  invalidCredentials,
  passwordRiskConfirmationFailed,
  permissionDenied,
  networkError,
  timeout,
  upstreamUnavailable,
  upstreamChanged,
  parseError,
  internalError,
  clientDisposed,
  confirmationRequired,
  intentExpired,
  operationConflict,
  outcomeUnknown,
}

/// bridge 对外的安全错误类别。
enum BridgeErrorKind {
  input,
  authentication,
  network,
  upstream,
  parse,
  internal,
}

/// 聚合登录结果。
class BridgeLoginOutcome {
  final BridgeLoginReadiness readiness;
  final List<BridgeRouteLoginResult> routes;
  final BridgeUserProfile? profile;

  const BridgeLoginOutcome({
    required this.readiness,
    required this.routes,
    this.profile,
  });

  @override
  int get hashCode => readiness.hashCode ^ routes.hashCode ^ profile.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeLoginOutcome &&
          runtimeType == other.runtimeType &&
          readiness == other.readiness &&
          routes == other.routes &&
          profile == other.profile;
}

/// 两条路线登录准备结果。
class BridgeLoginPreparation {
  final List<BridgeRouteLoginResult> routes;

  const BridgeLoginPreparation({required this.routes});

  @override
  int get hashCode => routes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeLoginPreparation &&
          runtimeType == other.runtimeType &&
          routes == other.routes;
}

/// 聚合登录状态。
enum BridgeLoginReadiness { allReady, partial, noneReady }

/// 网关探测三态结果。
enum BridgeNetworkState { campus, offCampus, unknown }

/// 一次 Core 路线决策的安全投影。
class BridgeRouteDecision {
  final BridgeRoutePolicy policy;
  final BridgeConnectionMode resolvedRoute;
  final BridgeNetworkState network;
  final BridgeConnectionMode initialRoute;
  final bool usedFallback;

  const BridgeRouteDecision({
    required this.policy,
    required this.resolvedRoute,
    required this.network,
    required this.initialRoute,
    required this.usedFallback,
  });

  @override
  int get hashCode =>
      policy.hashCode ^
      resolvedRoute.hashCode ^
      network.hashCode ^
      initialRoute.hashCode ^
      usedFallback.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeRouteDecision &&
          runtimeType == other.runtimeType &&
          policy == other.policy &&
          resolvedRoute == other.resolvedRoute &&
          network == other.network &&
          initialRoute == other.initialRoute &&
          usedFallback == other.usedFallback;
}

/// 单条路线登录结果。
class BridgeRouteLoginResult {
  final BridgeConnectionMode route;
  final BridgeRouteLoginState state;
  final BridgeSafeError? error;

  const BridgeRouteLoginResult({
    required this.route,
    required this.state,
    this.error,
  });

  @override
  int get hashCode => route.hashCode ^ state.hashCode ^ error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeRouteLoginResult &&
          runtimeType == other.runtimeType &&
          route == other.route &&
          state == other.state &&
          error == other.error;
}

/// 路线登录状态。
enum BridgeRouteLoginState { ready, failed }

/// 用户选择的路线策略。
enum BridgeRoutePolicy { auto, direct, webVpn }

/// 当前路线设置。
class BridgeRouteSettings {
  final BridgeRoutePolicy defaultPolicy;
  final List<BridgeConnectionMode> activeRoutes;

  const BridgeRouteSettings({
    required this.defaultPolicy,
    required this.activeRoutes,
  });

  @override
  int get hashCode => defaultPolicy.hashCode ^ activeRoutes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeRouteSettings &&
          runtimeType == other.runtimeType &&
          defaultPolicy == other.defaultPolicy &&
          activeRoutes == other.activeRoutes;
}

/// 带路线决策的用户资料。
class BridgeRoutedUserProfile {
  final BridgeUserProfile data;
  final BridgeRouteDecision route;

  const BridgeRoutedUserProfile({required this.data, required this.route});

  @override
  int get hashCode => data.hashCode ^ route.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeRoutedUserProfile &&
          runtimeType == other.runtimeType &&
          data == other.data &&
          route == other.route;
}

/// 路线错误的安全投影。
class BridgeSafeError {
  final String code;
  final String kind;
  final bool retryable;
  final String message;

  const BridgeSafeError({
    required this.code,
    required this.kind,
    required this.retryable,
    required this.message,
  });

  @override
  int get hashCode =>
      code.hashCode ^ kind.hashCode ^ retryable.hashCode ^ message.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeSafeError &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          kind == other.kind &&
          retryable == other.retryable &&
          message == other.message;
}

