    this.name,
    this.schoolId,
    this.email,
    this.phone,
    this.idCardTypeName,
  });

  @override
  int get hashCode =>
      username.hashCode ^
      name.hashCode ^
      schoolId.hashCode ^
      email.hashCode ^
      phone.hashCode ^
      idCardTypeName.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeUserProfile &&
          runtimeType == other.runtimeType &&
          username == other.username &&
          name == other.name &&
          schoolId == other.schoolId &&
          email == other.email &&
          phone == other.phone &&
          idCardTypeName == other.idCardTypeName;
}
